(7449038, 1178882, 149964, '<td valign="top">Yes. The extra brightness on this adds an element of surrealism. Like it.</td>', 'Yes. The extra brightness on this adds an element of surrealism. Like it.', '2016-04-08 16:33:07.000000', NULL, 1),
