(7449041, 1178708, 149964, '<td valign="top">Gorgeous colour contrasts. Enough blur to see movement without losing the overarching scene.</td>', 'Gorgeous colour contrasts. Enough blur to see movement without losing the overarching scene.', '2016-04-08 16:37:55.000000', NULL, 1),
(7449042, 1178696, 149964, '<td valign="top">Clever use of blown out sky to highlight building.</td>', 'Clever use of blown out sky to highlight building.', '2016-04-08 16:38:21.000000', NULL, 1),
(7449043, 1178881, 149964, '<td valign="top">Whilst I like the colours of the ''flawed'' light, from my point of view, it doesn''t enhance the scene.</td>', 'Whilst I like the colours of the ''flawed'' light, from my point of view, it doesn''t enhance the scene.', '2016-04-08 16:40:10.000000', NULL, 1),
