(7449047, 1178876, 149964, '<td valign="top">I like the overall composition but not getting a ''wow''. Am going to come back and vote later.</td>', 'I like the overall composition but not getting a ''wow''. Am going to come back and vote later.', '2016-04-08 16:44:07.000000', NULL, 1),
(7449049, 1178645, 149964, '<td valign="top">Oh my - very bold! Like the colours.</td>', 'Oh my - very bold! Like the colours.', '2016-04-08 16:45:04.000000', NULL, 1),
